script.setup:
// culori interpolates the same two colors in four color spaces, one band each:
// rgb, hsl, lab and oklch from top to bottom.
const culori = await ctx.utils.import("https://esm.sh/culori@4.0.1");
Object.assign(ctx.state, { culori, MODES: ["rgb", "hsl", "lab", "oklch"], ramp: new Float32Array(256 * 3),
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform vec3 u_ramp[256];
void main(){
  float row = floor((1.0 - v_uv.y) * 4.0);
  float x = v_uv.x * 63.0; int i = int(floor(x)); float f = fract(x);
  int base = int(row) * 64;
  vec3 c = mix(u_ramp[base + i], u_ramp[base + min(i + 1, 63)], f);
  float edge = fract((1.0 - v_uv.y) * 4.0);
  c *= smoothstep(0.0, 0.015, edge) * smoothstep(1.0, 0.985, edge);
  outColor = vec4(c, 1.0);
}") });

script.render:
const s = ctx.state, { culori } = s, u = ctx.uniforms;
const turn = (c) => {
  const o = culori.oklch({ mode: "rgb", r: c[0], g: c[1], b: c[2] });
  return { ...o, h: ((o.h ?? 0) + ctx.time * u.u_spin) % 360 };
};
const a = turn(u.u_from), b = turn(u.u_to);
s.MODES.forEach((mode, row) => {
  const mix = culori.interpolate([a, b], mode);
  for (let i = 0; i < 64; i++) {
    const c = culori.clampChroma(culori.rgb(mix(i / 63)), "rgb");
    s.ramp.set([c.r, c.g, c.b].map((v) => Math.min(1, Math.max(0, v ?? 0))), (row * 64 + i) * 3);
  }
});
ctx.gl.useProgram(s.p);
ctx.utils.drawFullscreen(s.p, { u_ramp: s.ramp });
